<div class="card mb-4"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 mb-1">Current Office Assignments</h2><p class="text-muted small mb-0">Authoritative organizational context, separate from ARPA duties.</p></div><?php if(Auth::can('officer.office-assignment.create')): ?><a class="btn btn-primary" href="<?= e(url('hr/officers/'.$officer['id'].'/offices/assign')) ?>">Assign Office</a><?php endif; ?></div><div class="table-responsive"><table class="table table-striped table-hover align-middle"><thead><tr><th>Office DAD Number</th><th>Office Name</th><th>Type</th><th>Related Location</th><th>Effective From</th><th>Primary</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php if(!$current_offices): ?><tr><td colspan="8" class="text-center text-muted">Office not assigned.</td></tr><?php endif; ?><?php foreach($current_offices as $a): ?><tr><td><?= e($a['office_dad']) ?></td><td><?= e($a['office_name']) ?></td><td><?= e($a['office_type']) ?></td><td><?= e(trim(($a['location_dad']??'').' '.($a['location_name']??''))?:$dash) ?></td><td><?= e($a['effective_from']) ?></td><td><?= $a['is_primary']?'Yes':'No' ?></td><td><?= DataTableFormat::badge('CURRENT') ?></td><td><?php if(Auth::can('officer.office-assignment.set-primary')&&!$a['is_primary']): ?><form class="d-inline" method="post" action="<?= e(url('hr/officers/'.$officer['id'].'/offices/'.$a['id'].'/primary')) ?>"><?= Csrf::field() ?><button class="btn btn-sm btn-outline-secondary">Set Primary</button></form><?php endif; ?><?php if(Auth::can('officer.office-assignment.end')): ?><form class="d-inline-flex gap-1" method="post" action="<?= e(url('hr/officers/'.$officer['id'].'/offices/'.$a['id'].'/end')) ?>"><?= Csrf::field() ?><input class="form-control form-control-sm" type="date" name="effective_to" required aria-label="Effective To"><input class="form-control form-control-sm" name="reason" required placeholder="End reason"><button class="btn btn-sm btn-outline-danger">End</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php $renderOperational=function(string $title,array $rows,array $workflow,bool $subject=false)use($dash){ ?><div class="card mb-4"><div class="card-body"><h2 class="h5"><?= e($title) ?></h2><div class="table-responsive"><table class="table table-striped table-hover align-middle"><thead><tr><th>Type / Function</th><th>ARPA Division / Subject</th><th>ASC</th><th>District</th><th>Effective From</th><th>Effective To</th><th>End Reason</th><th>Status</th><th>Source / Workflow</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="9" class="text-center text-muted">No records found.</td></tr><?php endif; ?><?php foreach($rows as $r): ?><tr><td><?= e(str_replace('_',' ',$subject?$r['subject_kind_snapshot']:$r['appointment_type'])) ?><?php if($subject&&!empty($r['sub_designation_name'])): ?><div class="small text-muted">Sub-designation: <?= e($r['sub_designation_name']) ?></div><?php endif; ?></td><td><?= e(($subject?$r['subject_name_snapshot']:$r['arpa_name_snapshot'])?:$dash) ?></td><td><?= e($r['asc_name_snapshot']?:$dash) ?></td><td><?= e($r['district_name_snapshot']?:$dash) ?></td><td><?= DataTableFormat::date($r['effective_from']) ?></td><td><?= DataTableFormat::date($r['effective_to'],$dash) ?></td><td><?= e($r['end_reason']?:$dash) ?></td><td><?= DataTableFormat::badge($r['profile_period']==='FUTURE'?'SCHEDULED':($r['profile_period']==='CURRENT'?'CURRENT':'ENDED')) ?></td><td><?= DataTableFormat::badge($r['record_origin']) ?><?php if(!empty($r['letter_reference_id'])): ?><div class="small">Letter: <?= e($r['letter_type']?:$r['letter_reference_id']) ?><?= !empty($r['letter_date'])?' / '.e($r['letter_date']):'' ?></div><?php endif; ?><?php if(!empty($workflow[$r['request_id']])): ?><details><summary>Workflow history</summary><?php foreach($workflow[$r['request_id']] as $w): ?><div class="small"><strong><?= e($w['stage'].' '.$w['action']) ?>:</strong> <?= e($w['display_name']?:$w['username']) ?><br><?= $w['action_at']?DataTableFormat::dateTime($w['action_at']):e('Unavailable from legacy source') ?></div><?php endforeach; ?></details><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php }; ?>
<?php $renderOperational('Current ARPA Appointments',$current_appointments,$appointment_workflow);$renderOperational('Current ASC Subject / Function Assignments',$current_subjects,$subject_workflow,true);$renderOperational('Scheduled / Future ARPA Appointments',$future_appointments,$appointment_workflow);$renderOperational('Scheduled / Future Subject / Function Assignments',$future_subjects,$subject_workflow,true);$renderOperational('Historical ARPA Appointments / Functions',$previous_appointments,$appointment_workflow);$renderOperational('Historical Subject / Function Assignments',$previous_subjects,$subject_workflow,true); ?>
<?php if($appointment_corrections): ?><div class="card mb-4"><div class="card-body"><h2 class="h5">Appointment Data Correction History</h2><p class="small text-muted">Append-only corrections to the DEMS representation. Original legacy evidence remains preserved.</p><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Issue</th><th>ASC / ARPA Division</th><th>Action</th><th>Resolution</th><th>Reason</th><th>Corrected By</th><th>Corrected At</th><th></th></tr></thead><tbody><?php foreach($appointment_corrections as $c): ?><tr><td><code><?= e($c['issue_type']) ?></code></td><td><?= e(($c['asc_name']?:$dash).' / '.($c['arpa_name_snapshot']?:$dash)) ?></td><td><?= DataTableFormat::badge($c['correction_action']) ?></td><td><?= DataTableFormat::badge($c['resolution_status']) ?></td><td><?= e($c['correction_reason']) ?></td><td><?= e($c['display_name']?:$c['username']) ?></td><td><?= DataTableFormat::dateTime($c['corrected_at']) ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= e(url('hr/arpa-appointments/issues/corrections/'.$c['id'])) ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php endif; ?>
<?php if($legacy_current||$legacy_future||$legacy_previous): ?><div class="alert alert-info"><strong>Legacy Appointment History - Not Yet Migrated</strong><br><span class="badge text-bg-warning">LEGACY / NOT YET MIGRATED</span> These reconciled legacy records are a read-only preview and are not operational DEMS appointments.</div><?php endif; ?>
<?php $renderLegacy=function(string $title,array $rows)use($dash,$workflowLabels){ ?><div class="card mb-4"><div class="card-body"><h2 class="h5"><?= e($title) ?></h2><div class="table-responsive"><table class="table table-striped table-hover align-middle"><thead><tr><th>Type / Function</th><th>Division / Subject</th><th>ASC / District</th><th>Effective Period</th><th>End Reason</th><th>Workflow / Provenance</th><th>Exceptions</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7" class="text-center text-muted">No records found.</td></tr><?php endif; ?><?php foreach($rows as $r): ?><tr><td><?= DataTableFormat::badge('LEGACY') ?><div><?= e(str_replace('_',' ',$r['appointment_type']?:$r['subject_kind'])) ?></div></td><td><?= e(($r['arpa_name']?:str_replace('_',' ',$r['subject_kind']??''))?:$dash) ?></td><td><?= e(($r['asc_name']?:$dash).' / '.($r['district_name']?:$dash)) ?></td><td><?= DataTableFormat::date($r['effective_from'],$dash) ?> to <?= DataTableFormat::date($r['effective_to'],'Open') ?></td><td><?= e($r['legacy_reason_text']?:$dash) ?></td><td><?= DataTableFormat::badge($r['workflow_state']) ?><details><summary>Workflow identities</summary><?php foreach($workflowLabels as $key=>$label):$actor=$r['workflow_json'][$key]??null; ?><div><strong><?= e($label) ?>:</strong> <?= e($actor['target_user']['display_name']??$actor['target_user']['username']??'Not recorded') ?><br><small class="text-muted"><?= $actor&&$actor['legacy_user_id']?'Unavailable from legacy source':'—' ?></small></div><?php endforeach; ?><div class="mt-2"><strong>Source:</strong> <?= e(implode(', ',$r['source_references_json'])) ?></div></details></td><td><?php foreach($r['historical_exception_types_json'] as $x): ?><?= DataTableFormat::badge($x) ?> <?php endforeach; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php }; ?>
<?php $renderLegacy('Current Legacy Candidates',$legacy_current);$renderLegacy('Scheduled / Future Legacy Candidates',$legacy_future);$renderLegacy('Historical / Ended Legacy Records',$legacy_previous); ?>
<?php if(!$current_appointments&&!$future_appointments&&!$previous_appointments&&!$current_subjects&&!$future_subjects&&!$previous_subjects&&!$legacy_current&&!$legacy_future&&!$legacy_previous): ?><div class="alert alert-light border">No appointment history is available for this Officer.</div><?php endif; ?>
<div class="card mb-4"><div class="card-body"><h2 class="h5">Historical Office Assignments</h2><div class="table-responsive"><table class="table table-striped align-middle"><thead><tr><th>Office</th><th>Effective From</th><th>Effective To</th><th>Reason</th><th>Official Reference</th><th>Provenance</th></tr></thead><tbody><?php if(!$historical_offices): ?><tr><td colspan="6" class="text-center text-muted">No historical Office assignments.</td></tr><?php endif; ?><?php foreach($historical_offices as $a): ?><tr><td><?= e($a['office_dad'].' - '.$a['office_name']) ?></td><td><?= DataTableFormat::date($a['effective_from']) ?></td><td><?= DataTableFormat::date($a['effective_to'],$dash) ?></td><td><?= e($a['reason']?:$dash) ?></td><td><?= e($a['official_reference']?:$dash) ?></td><td><?= DataTableFormat::badge($a['record_origin']) ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
